  PRIMARY KEY ("slug"),
  CONSTRAINT "booking_event_types_kind_check" CHECK ((kind IN ('nurse', 'clinic', 'company'))),
  CONSTRAINT "booking_event_types_slot_minutes_check" CHECK (((slot_minutes IS NULL) OR ((slot_minutes >= 5) AND (slot_minutes <= 240)))),
  CONSTRAINT "booking_event_types_buffer_minutes_check" CHECK (((buffer_minutes IS NULL) OR ((buffer_minutes >= 0) AND (buffer_minutes <= 120)))),
  CONSTRAINT "booking_event_types_min_notice_hours_check" CHECK (((min_notice_hours IS NULL) OR ((min_notice_hours >= 0) AND (min_notice_hours <= 720)))),
  CONSTRAINT "booking_event_types_horizon_days_check" CHECK (((horizon_days IS NULL) OR ((horizon_days >= 1) AND (horizon_days <= 90))))
);
CREATE TABLE IF NOT EXISTS "booking_hosts" (
