);
CREATE TABLE IF NOT EXISTS "bookings" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "kind" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT,
  "phone" TEXT,
  "note" TEXT,
  "company" TEXT,
  "selections" TEXT NOT NULL DEFAULT '{}' CHECK ("selections" IS NULL OR json_valid("selections")),
  "starts_at" TEXT NOT NULL,
  "ends_at" TEXT NOT NULL,
