  "access_token" TEXT,
  "expiry" TEXT,
  "google_email" TEXT,
  "signature_html" TEXT,
  "signature_fetched_at" TEXT,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
  PRIMARY KEY ("owner_user_id")
);
CREATE TABLE IF NOT EXISTS "google_calendar_tokens" (
  "user_id" TEXT NOT NULL,
  "refresh_token" TEXT,
  "access_token" TEXT,
  "expiry" TEXT,
  "google_email" TEXT,
  "sees_all" INTEGER NOT NULL DEFAULT 0 CHECK ("sees_all" IN (0, 1)),
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
  PRIMARY KEY ("user_id")
);
CREATE TABLE IF NOT EXISTS "inbox_sla_nudges" (
  "key" TEXT NOT NULL,
