);
CREATE TABLE IF NOT EXISTS "phase_slots" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))),
  "org_id" TEXT,
  "phase" TEXT NOT NULL,
  "position" INTEGER NOT NULL DEFAULT 0,
  "type" TEXT NOT NULL DEFAULT 'simple',
  "label" TEXT NOT NULL,
  "label_trans" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000+00:00'),
  "action_type" TEXT DEFAULT 'upload',
  "instructions" TEXT,
  "template_pdf_path" TEXT,
  "form_fields" TEXT CHECK ("form_fields" IS NULL OR json_valid("form_fields")),
  "admin_signs" INTEGER NOT NULL DEFAULT 0 CHECK ("admin_signs" IN (0, 1)),
  "candidate_signs" INTEGER NOT NULL DEFAULT 0 CHECK ("candidate_signs" IN (0, 1)),
  "admin_fills" INTEGER NOT NULL DEFAULT 0 CHECK ("admin_fills" IN (0, 1)),
  "candidate_fills" INTEGER NOT NULL DEFAULT 0 CHECK ("candidate_fills" IN (0, 1)),
  "candidate_signature_zone" TEXT CHECK ("candidate_signature_zone" IS NULL OR json_valid("candidate_signature_zone")),
  "pdf_has_native_fields" INTEGER NOT NULL DEFAULT 0 CHECK ("pdf_has_native_fields" IN (0, 1)),
