CREATE INDEX IF NOT EXISTS "idx_journey_due" ON "candidate_journey_items" (candidate_user_id, done, due_date);
CREATE INDEX IF NOT EXISTS "idx_journey_candidate" ON "candidate_journey_items" (candidate_user_id);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_journey_preset" ON "candidate_journey_items" (candidate_user_id, preset_key);
CREATE INDEX IF NOT EXISTS "assistant_reminders_owner_idx" ON "assistant_reminders" (owner_user_id, done, due_date);
CREATE INDEX IF NOT EXISTS "assistant_reminders_ping_idx" ON "assistant_reminders" (owner_user_id, last_ping_message_id) WHERE (last_ping_message_id IS NOT NULL);
